function leerEml(contenido) {
  const t = String(contenido).replace(/\r\n/g, '\n');
  const corte = t.indexOf('\n\n');
  const cabecera = corte === -1 ? t : t.slice(0, corte);
  const cuerpo = corte === -1 ? '' : t.slice(corte + 2);
  const json = { textPlain: cuerpo, textHtml: '', metadata: {} };
  for (const linea of cabecera.split('\n')) {
    const m = linea.match(/^([A-Za-z-]+):\s*(.*)$/);
    if (!m) continue;
    const nombre = m[1].toLowerCase();
    if (['from', 'to', 'subject', 'date', 'cc'].includes(nombre)) json[nombre] = m[2];
    else json.metadata[nombre] = m[2];
  }
  return json;
}

function huella(s) {
  // FNV-1a de 32 bits: identifica un correo sin Message-ID.
  let h = 0x811c9dc5;
  for (const c of String(s)) { h ^= c.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

// Una línea del banco: "Importe: 10,00 EUR" (Bizum) o "Importe .......... 12,00 EUR" (transferencia).
const lineaBanco = campo => new RegExp(`^[ \\t]*${campo}[ \\t]*(?::|\\.{2,})`, 'mi');

function prepararCorreo(c) {
  const remitente = String(c.from?.text ?? c.from ?? '');
  const asunto = String(c.subject ?? '');
  const texto = String(c.textPlain || String(c.textHtml ?? '').replace(/<[^>]+>/g, ' ')).trim();
  const messageId = c.metadata?.['message-id'] ?? '';
  const id_correo = messageId || 'huella-' + huella(`${remitente}\n${asunto}\n${texto}`);
  // Filtro previo sin IA: solo es un pago si trae las líneas "Importe" y "Ordenante" del banco.
  // Los avisos de los flujos llegan al mismo buzón pero nunca usan ese formato.
  const es_pago = lineaBanco('Importe').test(texto) && lineaBanco('Ordenante').test(texto);
  const tipo = /transferencia/i.test(`${asunto}\n${texto}`) ? 'transferencia' : 'bizum';
  return { id_correo, remitente, asunto, texto, tipo, es_pago };
}

// Un item por correo y modelo, con el mismo prompt que usa "03 - Abonos a distancia".
// A diferencia del flujo 03, aquí también va el correo de publicidad: así se ve si el modelo inventa datos.
const PROMPT = "Eres un extractor de datos. Lees un aviso de un banco sobre un pago recibido (Bizum o transferencia) y devuelves SOLO un objeto JSON, sin explicaciones ni bloques de código, con estos tres campos de texto:\n- \"ordenante\": lo que aparece en la línea \"Ordenante\", copiado tal cual.\n- \"importe\": lo que aparece en la línea \"Importe\", copiado tal cual (por ejemplo \"10,00 EUR\").\n- \"concepto\": lo que aparece en la línea \"Concepto\", copiado tal cual. Si esa línea está vacía o no existe, devuelve \"\".\nReglas: no inventes ni completes datos, no corrijas nombres, no uses el texto de otras líneas para rellenar un campo. Si un dato no aparece, devuelve \"\".\nEjemplo de respuesta: {\"ordenante\": \"ANA PEREZ\", \"importe\": \"15,00 EUR\", \"concepto\": \"botas\"}";
const MODELOS = ["openai/gpt-oss-20b","qwen/qwen3.8-27b"];
const salida = [];
for (const i of $input.all()) {
  const fichero = String(i.json.fichero ?? '').replace(/\.eml$/, '');
  const c = prepararCorreo(leerEml(i.json.data));
  const usuario = `Asunto: ${c.asunto}\n\n${c.texto}`;
  for (const modelo of MODELOS) {
    salida.push({ json: { fichero, modelo, enviado: usuario,
      body: { model: modelo, temperature: 0, max_tokens: 300,
        messages: [{ role: 'system', content: PROMPT }, { role: 'user', content: usuario }] } } });
  }
}
return salida;

function importeANumero(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v * 100) / 100 : null;
  let t = String(v ?? '').replace(/eur|€|\s/gi, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  if (!/^\d+(\.\d+)?$/.test(t)) return null;
  return Math.round(Number(t) * 100) / 100;
}

function validarExtraccion(respuesta) {
  let datos = respuesta;
  if (typeof respuesta === 'string') {
    const m = respuesta.match(/\{[\s\S]*\}/);
    try { datos = m ? JSON.parse(m[0]) : null; } catch { datos = null; }
  }
  if (!datos || typeof datos !== 'object') {
    return { json_valido: false, ordenante: '', importe: null, concepto: '' };
  }
  const importe = importeANumero(datos.importe);
  return {
    json_valido: true,
    ordenante: String(datos.ordenante ?? '').trim(),
    importe: importe !== null && importe > 0 ? importe : null,
    concepto: String(datos.concepto ?? '').trim(),
  };
}

const ESPERADO = Object.fromEntries([["01_bizum_carmen","CARMEN RUIZ GARCIA",10,"zuecos"],["02_bizum_jorge","JORGE M.",20,"apartado 2 bota"],["03_transferencia_lucia","LUCIA GOMEZ PEREZ",12,"Liquidar mocasines"],["04_bizum_laura","LAURA O.",15,"deportivas"],["05_bizum_romero","ROMERO D",10,""],["06_bizum_paula","PAULA RAMOS LEON",20,"zapatillas running perdón por el retraso"],["07_transferencia_desconocido","ANTONIO FERNANDEZ SOTO",25,"botas"],["08_publicidad_banco","",null,""],["09_bizum_silvia","SILVIA CORTES",5,"abono sandalias"]].map(([f, ordenante, importe, concepto]) => [f, { ordenante, importe, concepto }]));
const igual = (a, b) => String(a ?? '').trim().toLowerCase() === String(b ?? '').trim().toLowerCase();
const pedidos = $('Preparar peticiones').all();
const filas = $input.all().map((it, i) => {
  const p = pedidos[i].json;
  const r = it.json;
  const ok = r.statusCode === 200;
  const texto = ok ? (r.body?.choices?.[0]?.message?.content ?? '') : '';
  // JSON válido = la respuesta entera es un objeto JSON, sin texto ni bloques de código alrededor.
  let jsonLimpio = false;
  try { const o = JSON.parse(texto.trim()); jsonLimpio = !!o && typeof o === 'object' && !Array.isArray(o); } catch {}
  const ex = validarExtraccion(texto);
  const e = ESPERADO[p.fichero];
  const campos = {
    ordenante: igual(ex.ordenante, e.ordenante),
    importe: (ex.importe ?? null) === e.importe,
    concepto: igual(ex.concepto, e.concepto),
  };
  const u = r.body?.usage ?? {};
  return { modelo: p.modelo, fichero: p.fichero, http: r.statusCode, json_limpio: jsonLimpio, json_util: ex.json_valido,
    ...campos, aciertos: Object.values(campos).filter(Boolean).length,
    segundos: u.total_time ?? null, tokens_entrada: u.prompt_tokens ?? null, tokens_salida: u.completion_tokens ?? null,
    respuesta: texto, error: ok ? '' : JSON.stringify(r.body).slice(0, 300) };
});
return filas.map(json => ({ json }));

// Una fila por modelo con las métricas de T-013.
const filas = $input.all().map(i => i.json);
const modelos = [...new Set(filas.map(f => f.modelo))];
const media = xs => xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null;
return modelos.map(m => {
  const fs = filas.filter(f => f.modelo === m);
  const t = fs.map(f => f.segundos).filter(x => typeof x === 'number').sort((a, b) => a - b);
  return { json: {
    modelo: m, correos: fs.length,
    ordenante: fs.filter(f => f.ordenante).length, importe: fs.filter(f => f.importe).length, concepto: fs.filter(f => f.concepto).length,
    campos_ok: fs.reduce((s, f) => s + f.aciertos, 0), campos_total: fs.length * 3,
    correos_perfectos: fs.filter(f => f.aciertos === 3).length,
    json_limpio: fs.filter(f => f.json_limpio).length, json_util: fs.filter(f => f.json_util).length,
    segundos_media: media(t), segundos_mediana: t.length ? t[Math.floor(t.length / 2)] : null, segundos_max: t.length ? t[t.length - 1] : null,
    tokens_salida_media: media(fs.map(f => f.tokens_salida).filter(x => typeof x === 'number')),
    errores_http: fs.filter(f => f.http !== 200).length,
  } };
});
